const business_statement = norm(mergedRow[BUSINESS_STATEMENT_FIELD]);
const combined_industry_niche = combineFields(mergedRow, INDUSTRY_FIELDS);
const combined_tools_preferences = combineFields(mergedRow, TOOL_PREF_FIELDS);
const doing_blueprint_priorities = norm(mergedRow[BLUEPRINT_PRIORITIES_FIELD]);
const reason_for_doer = norm(mergedRow[REASON_FOR_GETTING_A_DOER]);
const details_project = norm(mergedRow[DETAILS_OF_PROJECT]);
const big_project = norm(mergedRow[BIG_PROJECT_12_MOS]);
const top3_services = norm(mergedRow[TOP_3_SERVICES_PRODUCTS]);
const other_tasks_doer = norm(mergedRow[TASKS_DOER_CAN_DO]);

const website = norm(mergedRow[WEBSITE_FIELD]);

const social_media = combineFields(mergedRow, SOCIAL_MEDIA_FIELDS);
const staff_members = combineFields(mergedRow, STAFF_MEMBERS_FIELDS);
const brand_guidelines = combineFields(mergedRow, BRAND_GUIDELINES_FIELDS);
const logo = combineFields(mergedRow, LOGO_FIELDS);
const doer_university_badge = combineFields(mergedRow, DOER_UNIVERSITY_BADGE_FIELDS);

// --------------------
// Output: keep all base fields + add enrichment fields
// --------------------
return baseItems.map(it => {
  const base = it.json || {};

  const raw_data = {
    ...(base.raw_data || {}),
  };

  if (hasValue(social_media))
    raw_data.social_media = social_media;

  if (hasValue(staff_members))
    raw_data.staff_members = staff_members;

  if (hasValue(brand_guidelines))
    raw_data.brand_guidelines = brand_guidelines;

  if (hasValue(logo))
    raw_data.logo = logo;

  if (hasValue(doer_university_badge))
    raw_data.doer_university_badge = doer_university_badge;

  const next = {
    ...base,

    // always keep these extra columns too (optional. remove if you do not want them)
    website: website || "",
    business_description: business_statement || "",
    tools_required: combined_tools_preferences || "",
    reason_for_doer: reason_for_doer || "",
    details_project: details_project || "",
    big_project: big_project || "",
    top3_services: top3_services || "",
    other_tasks_doer: other_tasks_doer || "",
    raw_data,

  };

  // overrides (only when enrichment has value)
  if (hasValue(revenue_raw)) next.monthly_revenue = revenue_raw;
  if (hasValue(combined_industry_niche)) next.industry = combined_industry_niche;
  if (hasValue(doing_blueprint_priorities)) next.va_tasks = doing_blueprint_priorities;

  return { json: next };
});
